blocks.text:
constexpr uint8_t LED = 23;
uint32_t last = 0;
bool on = false;
void setup() {
  pinMode(LED, OUTPUT);
}
void loop() {
  uint32_t now = millis();
  if (uint32_t(now-last) >= 500) {
    last = now;
    on = !on;
    digitalWrite(LED, on);
  }
}

